-- Username is the B-tree search key; email and created_at are leaf payloads
CREATE INDEX idx_users_covering ON users (username) INCLUDE (email, created_at);

-- Query executed strictly via Index-Only Scan (Zero Heap Fetches!)
SELECT email, created_at 
FROM users 
WHERE username = 'alex_rivera';

CREATE INDEX idx_users_username_covering
ON users (username) INCLUDE (email, created_at);

VACUUM ANALYZE users;

EXPLAIN (ANALYZE, BUFFERS)
SELECT username, email, created_at
FROM users
WHERE username = 'ada';
-- Index Only Scan using idx_users_username_covering on users
--   Index Cond: (username = 'ada')
--   Heap Fetches: 0
